ok = True
for x in R:
    for k in ("s", "p"):
        m = Chem.MolFromSmiles(x[k])
        if m is None: print("BAD", x["id"], k, x[k]); ok = False
        else: x[k] = Chem.MolToSmiles(m)
    print(f'{x["id"]:18} {CalcMolFormula(Chem.MolFromSmiles(x["s"])):14} -> {CalcMolFormula(Chem.MolFromSmiles(x["p"]))}')
if not ok: sys.exit(1)
json.dump(R, open("os.path.join(os.path.dirname(os.path.abspath(__file__)), '')newrx.json", "w"), ensure_ascii=False)
print(len(R))
